  INSERT INTO lessons(chapter_id,prompt_character_id,learner_character_id,title,title_translation,description,description_translation,lesson_type,storyline_key,storyline_order,difficulty,estimated_duration_sec,sort_order,status,metadata) VALUES(v_chapter,v_c_sara,v_c_mia,'Mehr Schlaf planen','برای خواب بیشتر برنامه ریختن','Sara und Mia planen eine längere Nacht und vergleichen Schlafdauer und Tagesrhythmus.','سارا و میا برای خواب طولانی تر برنامه می ریزند و مدت خواب و برنامه روزانه را مقایسه می کنند.','story','mia-sara-b1-health-routine',13,55,180,1,'validated','{"relationship":"friends","context":"health-routine","cefr":"B1","storyArc":"plan-more-sleep"}'); SET v_l_1=LAST_INSERT_ID();
  INSERT INTO turns(lesson_id,character_id,sort_order,role,text,translation,difficulty,audio_url,audio_duration_ms,speech_target,speech_alternatives,tokens,grammar_title,grammar_note,grammar_data,metadata) VALUES(v_l_1,v_c_sara,1,'character','Hast du heute genug geschlafen?','امروز به اندازه کافی خوابیدی؟',55,NULL,NULL,NULL,NULL,'[{"surface":"Hast","lemma":"haben","translation":"داشتن","partOfSpeech":"verb"},{"surface":"du","lemma":"du","translation":"تو","partOfSpeech":"pronoun"},{"surface":"heute","lemma":"heute","translation":"امروز","partOfSpeech":"adverb"},{"surface":"genug","lemma":"genug","translation":"کافی","partOfSpeech":"adverb"},{"surface":"geschlafen","lemma":"schlafen","translation":"خوابیدن","partOfSpeech":"verb","suffix":"?"}]','Mit sollte über gesunde Gewohnheiten sprechen','با sollte توصیه یا تصمیم ملایم بیان می‌شود. قیدهای زمان و مقدار برنامهٔ خواب را دقیق‌تر می‌کنند.','{"focus":"sollte_sleep_routine","structures":["sollte recommendation","time expressions","separable aufstehen","damit purpose clause"]}','{"cefr":"B1","course":"de-fa","series":104}'); SET v_t_1=LAST_INSERT_ID();
  INSERT INTO turns(lesson_id,character_id,sort_order,role,text,translation,difficulty,audio_url,audio_duration_ms,speech_target,speech_alternatives,tokens,grammar_title,grammar_note,grammar_data,metadata) VALUES(v_l_1,v_c_mia,2,'learner','Nein, ich habe nicht genug geschlafen.','نه، به اندازه کافی نخوابیدم.',55,NULL,NULL,'nein ich habe nicht genug geschlafen',NULL,'[{"surface":"Nein","lemma":"nein","translation":"نه","partOfSpeech":"interjection","suffix":","},{"surface":"ich","lemma":"ich","translation":"من","partOfSpeech":"pronoun"},{"surface":"habe","lemma":"haben","translation":"داشتن","partOfSpeech":"verb"},{"surface":"nicht","lemma":"nicht","translation":"نه / نیست","partOfSpeech":"adverb"},{"surface":"genug","lemma":"genug","translation":"کافی","partOfSpeech":"adverb"},{"surface":"geschlafen","lemma":"schlafen","translation":"خوابیدن","partOfSpeech":"verb","suffix":"."}]','Mit sollte über gesunde Gewohnheiten sprechen','با sollte توصیه یا تصمیم ملایم بیان می‌شود. قیدهای زمان و مقدار برنامهٔ خواب را دقیق‌تر می‌کنند.','{"focus":"sollte_sleep_routine","structures":["sollte recommendation","time expressions","separable aufstehen","damit purpose clause"]}','{"cefr":"B1","course":"de-fa","series":104}'); SET v_t_2=LAST_INSERT_ID();
  INSERT INTO turns(lesson_id,character_id,sort_order,role,text,translation,difficulty,audio_url,audio_duration_ms,speech_target,speech_alternatives,tokens,grammar_title,grammar_note,grammar_data,metadata) VALUES(v_l_1,v_c_sara,3,'character','Dann solltest du heute früh ins Bett gehen.','پس بهتر است امروز زود به تخت بروی.',55,NULL,NULL,NULL,NULL,'[{"surface":"Dann","lemma":"dann","translation":"بعد / سپس","partOfSpeech":"adverb"},{"surface":"solltest","lemma":"sollen","translation":"باید / قرار است","partOfSpeech":"verb"},{"surface":"du","lemma":"du","translation":"تو","partOfSpeech":"pronoun"},{"surface":"heute","lemma":"heute","translation":"امروز","partOfSpeech":"adverb"},{"surface":"früh","lemma":"früh","translation":"زودتر","partOfSpeech":"adverb"},{"surface":"ins","lemma":"in","translation":"در / داخل","partOfSpeech":"preposition"},{"surface":"Bett","lemma":"Bett","translation":"تخت","partOfSpeech":"noun"},{"surface":"gehen","lemma":"gehen","translation":"رفتن","partOfSpeech":"verb","suffix":"."}]','Mit sollte über gesunde Gewohnheiten sprechen','با sollte توصیه یا تصمیم ملایم بیان می‌شود. قیدهای زمان و مقدار برنامهٔ خواب را دقیق‌تر می‌کنند.','{"focus":"sollte_sleep_routine","structures":["sollte recommendation","time expressions","separable aufstehen","damit purpose clause"]}','{"cefr":"B1","course":"de-fa","series":104}'); SET v_t_3=LAST_INSERT_ID();
