  INSERT INTO lessons(chapter_id,prompt_character_id,learner_character_id,title,title_translation,description,description_translation,lesson_type,storyline_key,storyline_order,difficulty,estimated_duration_sec,sort_order,status,metadata) VALUES(v_chapter,v_c_sara,v_c_mia,'Das Handy am Abend','گوشی در شب','Mia erkennt, wie der Bildschirm ihren Schlaf stört, und entscheidet sich für eine frühere Handy-Pause.','میا متوجه می شود صفحه نمایش چطور خوابش را مختل می کند و تصمیم می گیرد گوشی را زودتر کنار بگذارد.','story','mia-sara-b1-health-routine',14,55,180,2,'validated','{"relationship":"friends","context":"health-routine","cefr":"B1","storyArc":"reduce-evening-screen"}'); SET v_l_2=LAST_INSERT_ID();
  INSERT INTO turns(lesson_id,character_id,sort_order,role,text,translation,difficulty,audio_url,audio_duration_ms,speech_target,speech_alternatives,tokens,grammar_title,grammar_note,grammar_data,metadata) VALUES(v_l_2,v_c_sara,1,'character','Was machst du am Abend?','شب ها چه کار می کنی؟',55,NULL,NULL,NULL,NULL,'[{"surface":"Was","lemma":"was","translation":"چی / چه","partOfSpeech":"pronoun"},{"surface":"machst","lemma":"machen","translation":"انجام دادن","partOfSpeech":"verb"},{"surface":"du","lemma":"du","translation":"تو","partOfSpeech":"pronoun"},{"surface":"am","lemma":"an","translation":"در / در روز","partOfSpeech":"preposition"},{"surface":"Abend","lemma":"Abend","translation":"عصر / شب","partOfSpeech":"noun","suffix":"?"}]','Mit sollte über gesunde Gewohnheiten sprechen','با sollte توصیه یا تصمیم ملایم بیان می‌شود. قیدهای زمان و مقدار برنامهٔ خواب را دقیق‌تر می‌کنند.','{"focus":"sollte_sleep_routine","structures":["sollte recommendation","time expressions","separable aufstehen","damit purpose clause"]}','{"cefr":"B1","course":"de-fa","series":104}'); SET v_t_7=LAST_INSERT_ID();
